#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int* createTargetArray(int* nums, int numsSize, int* index, int indexSize, int* returnSize) {
    int* target = (int*)malloc(numsSize * sizeof(int));
    int size = 0;
    for (int i = 0; i < numsSize; i++) {
        int p = index[i];
        for (int j = size; j > p; j--) target[j] = target[j - 1];
        target[p] = nums[i];
        size++;
    }
    *returnSize = size;
    return target;
}

static void parseArray(const char* s, int* out, int* n) {
    *n = 0;
    const char* p = s;
    while (*p && *p != '[') p++;
    if (*p == '[') p++;
    while (*p && *p != ']') {
        char* end;
        long v = strtol(p, &end, 10);
        if (p == end) { p++; continue; }
        out[(*n)++] = (int)v;
        p = end;
        while (*p == ' ' || *p == ',') p++;
    }
}

