    static String[] readArrayRaw(String s) {
        s = s.trim();
        if (s.equals("[]")) return new String[0];
        s = s.substring(1, s.length()-1);
        java.util.List<String> parts = new java.util.ArrayList<>();
        int depth=0, start=0;
        for (int i=0; i<s.length(); i++) {
            char c=s.charAt(i);
            if (c=='[') depth++; else if (c==']') depth--;
            else if (c==',' && depth==0) { parts.add(s.substring(start,i).trim()); start=i+1; }
        }
        parts.add(s.substring(start).trim());
        return parts.toArray(new String[0]);
    }
    static int[] toIntArray(String s) {
        String[] parts = readArrayRaw(s);
        int[] arr = new int[parts.length];
        for (int i=0; i<parts.length; i++) arr[i] = Integer.parseInt(parts[i].trim());
        return arr;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        String raw = line.substring(1, line.length()-1);
        int depth=0, start=0, split=-1;
        for (int i=0; i<raw.length(); i++) {
            char c=raw.charAt(i);
            if (c=='[') depth++; else if (c==']') depth--;
            else if (c==',' && depth==0) { split=i; break; }
